 for en,zh,n in [('Trisolian','特里索兰','星系名，沿稿'),('Theodulus Pallisar','西奥多勒斯·帕利萨','辅军精锐毁灭士，沿稿'),('Hester Aspertia Sigma-Sigma','赫斯特·阿斯佩尔蒂亚·西格玛-西格玛','女统御贤者，沿稿'),('Magos Domina','统御贤者','女性指挥官职衔，暂沿；非 Tech-Priest Dominus 官译'),('Myrmidon Destructor','辅军精锐毁灭士','机械教兵种，沿现稿，基于 Auxilia Myrmidon 核心'),('Heptaligon','七边','具体设施性质待核，沿稿'),('Hugin','福金号','鲁斯私人风暴鸟，沿稿')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿','篇0802',n])+'\n')
